/**
 * Content database schema (PostgreSQL 17, Drizzle ORM). Phase B.
 * Design and rules: docs/admin-database.md; approved architecture §17, review §C.
 *
 * Pattern for every translatable entity:
 *   <entity>              language-independent data: stable key, status, order, relations, media
 *   <entity>_translations one row per language: texts, slug, SEO texts, translation status
 *
 * - Primary keys are UUIDv7 generated by the application; `key` is the stable text ID of the
 *   content layer (e.g. "project-solbar-israel"), unique and never changed.
 * - Relations between content entities are foreign keys with ON DELETE RESTRICT, so a
 *   referenced item can never disappear silently. Translation and child rows cascade.
 * - JSONB only for ordered lists inside a translation and code-defined slot maps; every JSONB
 *   column has a Zod schema in @soltex/core/content (jsonb.ts) and the table has schema_version.
 * - `page_list_items.structure` is `json`, not `jsonb`: it is an arbitrary code-defined object
 *   whose key order is part of the content (jsonb would reorder keys). See docs/admin-database.md.
 */
import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  bigint,
  boolean,
  check,
  customType,
  index,
  date,
  integer,
  json,
  jsonb,
  pgEnum,
  pgSequence,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import { v7 as uuidv7 } from 'uuid';

// ---------------------------------------------------------------------------
// Enums
// ---------------------------------------------------------------------------

export const contentStatus = pgEnum('content_status', ['draft', 'published', 'archived']);
export const translationState = pgEnum('translation_state', ['missing', 'in_progress', 'approved']);
export const mediaKind = pgEnum('media_kind', ['image', 'video']);
export const pageKind = pgEnum('page_kind', ['page', 'template']);
export const patentLegalStatus = pgEnum('patent_legal_status', ['granted', 'application']);
export const redirectSource = pgEnum('redirect_source', ['manual', 'slug_change', 'import']);
export const mediaSource = pgEnum('media_source', ['legacy', 'upload']);

// ---------------------------------------------------------------------------
// Shared column sets
// ---------------------------------------------------------------------------

const pk = () => uuid('id').primaryKey().$defaultFn(() => uuidv7());
const stableKey = () => text('key').notNull().unique();
const audit = () => ({
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  // Users are never deleted (only disabled), so these references are RESTRICT (Phase C).
  createdBy: uuid('created_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
  updatedBy: uuid('updated_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
});

/** Columns of every publishable content entity. */
const entity = () => ({
  id: pk(),
  key: stableKey(),
  status: contentStatus('status').notNull().default('draft'),
  position: integer('position').notNull(),
  sourceLocale: text('source_locale')
    .notNull()
    .default('en')
    .references(() => locales.code),
  version: integer('version').notNull().default(1),
  /**
   * Revision of the source-language TRANSLATABLE text (Phase F, migration 0004). Raised by one
   * whenever a translated field of the source language changes; never by images, order, status,
   * slug or other language-independent data. Translations record the revision they were approved
   * against, so "outdated" = approved for an older revision (docs/admin-translations.md §2).
   */
  sourceRevision: integer('source_revision').notNull().default(1),
  publishedAt: timestamp('published_at', { withTimezone: true }),
  archivedAt: timestamp('archived_at', { withTimezone: true }),
  schemaVersion: smallint('schema_version').notNull().default(1),
  ...audit(),
});

/** Columns of every translation row (one row per entity and language). */
const translation = () => ({
  locale: text('locale')
    .notNull()
    .references(() => locales.code),
  /** null for the source language; workflow state for translations. */
  trStatus: translationState('tr_status'),
  /** Hash of the source-language fields when this translation was approved. */
  approvedSourceHash: text('approved_source_hash'),
  approvedAt: date('approved_at', { mode: 'string' }),
  schemaVersion: smallint('schema_version').notNull().default(1),
  ...audit(),
});

/**
 * Review tracking of the translation rows of the seven admin-managed entities (Phase F, migration
 * 0004). Not on settings_translations (settings are not edited in the admin yet).
 */
const translationReview = () => ({
  /** Concurrency token of this language row (If-Match of the translation editor). */
  version: integer('version').notNull().default(1),
  /** Entity source_revision this translation was approved against; null = not approved in the database. */
  approvedSourceRevision: integer('approved_source_revision'),
  approvedBy: uuid('approved_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
  /** Entity source_revision the translator last saved against (shows "source changed since"). */
  editedSourceRevision: integer('edited_source_revision'),
});

/** Per-language SEO texts of routable entities (null = frontend default template). */
const seoTexts = () => ({
  seoMetaTitle: text('seo_meta_title'),
  seoMetaDescription: text('seo_meta_description'),
});

// ---------------------------------------------------------------------------
// Reference data
// ---------------------------------------------------------------------------

export const locales = pgTable('locales', {
  code: text('code').primaryKey(),
  position: smallint('position').notNull().unique(),
  isSource: boolean('is_source').notNull().default(false),
});

// ---------------------------------------------------------------------------
// Media
// ---------------------------------------------------------------------------

export const media = pgTable('media', {
  id: pk(),
  key: stableKey(),
  kind: mediaKind('kind').notNull(),
  /** Public path or URL of the file (today: site-relative, e.g. "/images/x.jpg"). */
  src: text('src').notNull(),
  width: integer('width'),
  height: integer('height'),
  version: integer('version').notNull().default(1),
  /** Phase J (migration 0007): `legacy` = imported as is (/images, /videos); `upload` = media library. */
  source: mediaSource('source').notNull().default('legacy'),
  /** Uploaded file, relative to MEDIA_DIR (originals/<yyyy>/<uuid>.<ext>); null for legacy files. */
  storagePath: text('storage_path'),
  /** Name of the uploaded file as the user had it (shown only; never used as a path). */
  originalName: text('original_name'),
  mime: text('mime'),
  bytes: bigint('bytes', { mode: 'number' }),
  /** sha256 of the uploaded bytes: duplicate detection. */
  sha256: text('sha256'),
  /**
   * MediaVariantsV1 (Phase J-2, migration 0008): `{ source, items: [{ src, width, height }] }`.
   * Valid only while `source` equals `src` (a replaced file gets new copies). Null = not made yet.
   */
  variants: jsonb('variants'),
  ...audit(),
}, (t) => [
  index('media_sha256').on(t.sha256),
  // An uploaded file lives only at a UUID path under originals/ and is served at /media/<that path>.
  check(
    'media_upload_path',
    sql`${t.source} <> 'upload' OR (${t.storagePath} ~ '^originals/[0-9]{4}/[0-9a-f-]{36}\\.(jpg|png|webp|avif|mp4)$' AND ${t.src} = ('/media/' || ${t.storagePath}))`
  ),
]);

export const mediaTranslations = pgTable(
  'media_translations',
  {
    mediaId: uuid('media_id')
      .notNull()
      .references(() => media.id, { onDelete: 'cascade' }),
    locale: text('locale')
      .notNull()
      .references(() => locales.code),
    alt: text('alt').notNull(),
    ...audit(),
  },
  (t) => [primaryKey({ columns: [t.mediaId, t.locale] })]
);

const mediaRef = (name: string) => uuid(name).references(() => media.id, { onDelete: 'restrict' });

