// ---------------------------------------------------------------------------
// Redirects (internal targets only in v1 — approved architecture §11.3)
// ---------------------------------------------------------------------------

export const redirects = pgTable(
  'redirects',
  {
    id: pk(),
    key: stableKey(),
    fromPath: text('from_path').notNull().unique(),
    toPath: text('to_path').notNull(),
    statusCode: smallint('status_code').notNull().default(301),
    allLocales: boolean('all_locales').notNull().default(true),
    source: redirectSource('source').notNull().default('manual'),
    /** Optimistic lock for edits in the admin (Phase I-2, migration 0006). */
    version: integer('version').notNull().default(1),
    hits: integer('hits').notNull().default(0),
    lastHitAt: timestamp('last_hit_at', { withTimezone: true }),
    ...audit(),
  },
  (t) => [
    check('redirects_status_code', sql`${t.statusCode} IN (301, 302)`),
    // Absolute paths only: no scheme, no host, no protocol-relative "//", no backslash, no control characters.
    check('redirects_from_internal', sql`${t.fromPath} ~ '^/([^/\\\\[:cntrl:]][^\\\\[:cntrl:]]*)?$'`),
    check('redirects_to_internal', sql`${t.toPath} ~ '^/([^/\\\\[:cntrl:]][^\\\\[:cntrl:]]*)?$'`),
    check('redirects_not_self', sql`${t.fromPath} <> ${t.toPath}`),
  ]
);

// ===========================================================================
// Phase C: users, sessions, authentication factors, audit log
// (approved architecture §7, §8, §17.2; docs/admin-auth.md)
// ===========================================================================

export const userRole = pgEnum('user_role', ['owner', 'admin', 'content_manager', 'editor', 'seo_specialist', 'marketer']);
export const userStatus = pgEnum('user_status', ['active', 'disabled']);
export const auditResult = pgEnum('audit_result', ['success', 'failure', 'denied']);
export const webauthnChallengePurpose = pgEnum('webauthn_challenge_purpose', ['registration', 'authentication']);

const bytea = customType<{ data: Uint8Array; driverData: Buffer }>({
  dataType: () => 'bytea',
  toDriver: (v) => Buffer.from(v),
  fromDriver: (v) => new Uint8Array(v),
});

export const users = pgTable(
  'users',
  {
    id: pk(),
    /** Normalised (trimmed, lower-cased) e-mail; unique. */
    email: text('email').notNull(),
    name: text('name').notNull(),
    role: userRole('role').notNull(),
    status: userStatus('status').notNull().default('active'),
    /** Argon2id PHC string. Never logged, never returned by the API. */
    passwordHash: text('password_hash').notNull(),
    passwordChangedAt: timestamp('password_changed_at', { withTimezone: true }).notNull().defaultNow(),
    failedLogins: integer('failed_logins').notNull().default(0),
    lastFailedLoginAt: timestamp('last_failed_login_at', { withTimezone: true }),
    lockedUntil: timestamp('locked_until', { withTimezone: true }),
    lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
    version: integer('version').notNull().default(1),
    ...audit(),
  },
  (t) => [unique('users_email').on(t.email), check('users_email_normalised', sql`${t.email} = lower(btrim(${t.email}))`)]
);

export const sessions = pgTable(
  'sessions',
  {
    /** Public identifier (listing / revoking a session); never the secret. */
    id: pk(),
    /** SHA-256 of the 256-bit random session token (the cookie value). */
    tokenHash: text('token_hash').notNull().unique(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** Authentication assurance: 1 = password only, 2 = password + second factor. */
    aal: smallint('aal').notNull().default(1),
    /** Last successful second-factor verification (step-up window). */
    mfaVerifiedAt: timestamp('mfa_verified_at', { withTimezone: true }),
    /** Failed second-factor attempts in this session (the session is revoked after 5). */
    mfaFailures: integer('mfa_failures').notNull().default(0),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    /** Absolute expiry; the idle timeout is enforced against last_seen_at. */
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    ipHash: text('ip_hash'),
    userAgent: text('user_agent'),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    revokedReason: text('revoked_reason'),
  },
  (t) => [index('sessions_user').on(t.userId), check('sessions_aal', sql`${t.aal} IN (1, 2)`)]
);

/** Browsers that completed a full login before; per-account lockout does not apply to them (§19). */
export const knownDevices = pgTable(
  'known_devices',
  {
    tokenHash: text('token_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  },
  (t) => [index('known_devices_user').on(t.userId)]
);

/** Passkeys / security keys. Only public data: the private key never leaves the authenticator. */
export const webauthnCredentials = pgTable(
  'webauthn_credentials',
  {
    id: pk(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** Credential ID (base64url), globally unique. */
    credentialId: text('credential_id').notNull().unique(),
    /** COSE public key. */
    publicKey: bytea('public_key').notNull(),
    signCount: bigint('sign_count', { mode: 'number' }).notNull().default(0),
    transports: text('transports').array().notNull().default(sql`ARRAY[]::text[]`),
    deviceType: text('device_type').notNull(),
    backedUp: boolean('backed_up').notNull(),
    name: text('name').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
  },
  (t) => [index('webauthn_credentials_user').on(t.userId)]
);

/** One-time WebAuthn challenges: short-lived, bound to a session and a purpose, consumed on use. */
export const webauthnChallenges = pgTable(
  'webauthn_challenges',
  {
    id: pk(),
    challenge: text('challenge').notNull().unique(),
    purpose: webauthnChallengePurpose('purpose').notNull(),
    sessionId: uuid('session_id')
      .notNull()
      .references(() => sessions.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
  },
  (t) => [index('webauthn_challenges_session').on(t.sessionId)]
);

/** TOTP (RFC 6238) fallback factor. The secret is encrypted (AES-256-GCM, key id in the value). */
export const totpCredentials = pgTable('totp_credentials', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  secretEncrypted: text('secret_encrypted').notNull(),
  /** null while enrollment is pending confirmation. */
  confirmedAt: timestamp('confirmed_at', { withTimezone: true }),
  /** Last accepted time step: a code can never be accepted twice. */
  lastTimeStep: bigint('last_time_step', { mode: 'number' }),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
});

/** One-time recovery codes, stored as SHA-256 only (128-bit random codes). */
export const recoveryCodes = pgTable(
  'recovery_codes',
  {
    id: pk(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    codeHash: text('code_hash').notNull().unique(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    usedAt: timestamp('used_at', { withTimezone: true }),
  },
  (t) => [index('recovery_codes_user').on(t.userId)]
);

/** Password reset tokens: single use, 30 minutes, stored as SHA-256 only. */
export const passwordResets = pgTable(
  'password_resets',
  {
    tokenHash: text('token_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
  },
  (t) => [index('password_resets_user').on(t.userId)]
);

/**
 * Append-only audit log (§17.2). The application role has INSERT and SELECT only, and a
 * trigger refuses UPDATE, DELETE and TRUNCATE even for the table owner
 * (drizzle/0003_audit_append_only.sql). Never contains passwords, tokens, codes or secrets.
 */
export const auditEvents = pgTable(
  'audit_events',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    at: timestamp('at', { withTimezone: true }).notNull().defaultNow(),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'restrict' }),
    action: text('action').notNull(),
    resourceType: text('resource_type'),
    resourceId: text('resource_id'),
    result: auditResult('result').notNull(),
    requestId: text('request_id'),
    ipHash: text('ip_hash'),
    userAgent: text('user_agent'),
    /** AuditSummaryV1: action-specific details without personal data or secrets. */
    summary: jsonb('summary').notNull().default(sql`'{}'::jsonb`),
    schemaVersion: smallint('schema_version').notNull().default(1),
  },
  (t) => [index('audit_events_at').on(t.at), index('audit_events_actor').on(t.actorId), index('audit_events_request').on(t.requestId)]
);


// ---------------------------------------------------------------------------
// Phase G: revisions, content snapshots, releases, preview (docs/admin-publishing.md)
// ---------------------------------------------------------------------------

export const revisionKind = pgEnum('revision_kind', [
  'baseline',
  'import',
  'create',
  'update',
  'archive',
  'unarchive',
  'publish',
  'unpublish',
  'translation',
  'approve',
  'reopen',
  'restore',
]);
export const releaseStatus = pgEnum('release_status', ['queued', 'building', 'validating', 'ready', 'active', 'retired', 'failed', 'superseded']);
export const releaseKind = pgEnum('release_kind', ['release', 'preview']);

/**
 * Revision history of the seven admin-managed entity types. Append-only (trigger refuses UPDATE
 * and DELETE; the application role has INSERT and SELECT only). `data` is the entity's full record
 * in the seed / ContentStore format (all languages, translation states, relations and media by
 * stable key), so any revision can be compared and restored, and a release snapshot is made of the
 * same records. No user data, no secrets.
 */
export const contentRevisions = pgTable(
  'content_revisions',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    /** pages | projects | technologies | products | epcm-stages | patents | videos */
    entityType: text('entity_type').notNull(),
    entityId: uuid('entity_id').notNull(),
    entityKey: text('entity_key').notNull(),
    /** 1, 2, 3 … per entity; never reused. */
    number: integer('number').notNull(),
    kind: revisionKind('kind').notNull(),
    /** Language of a translation change; null for source and state changes. */
    locale: text('locale').references(() => locales.code),
    /** Entity source_revision after the change (Phase F). */
    sourceRevision: integer('source_revision').notNull(),
    /** Entity version after the change (Phase E optimistic lock). */
    entityVersion: integer('entity_version').notNull(),
    /** Source-language title at the time (for lists). */
    title: text('title').notNull(),
    /** EntityRecordV1: the record in ContentStore format. */
    data: json('data').notNull(),
    /** RevisionSummaryV1: changed field names, restore origin… (no texts). */
    summary: jsonb('summary').notNull().default(sql`'{}'::jsonb`),
    schemaVersion: smallint('schema_version').notNull().default(1),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    createdBy: uuid('created_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
  },
  (t) => [
    unique('content_revisions_number').on(t.entityType, t.entityId, t.number),
    index('content_revisions_created').on(t.createdAt),
    index('content_revisions_entity').on(t.entityType, t.entityId),
  ]
);

/**
 * Immutable content snapshot a release (or a preview) is built from: the ContentStore in seed
 * format, its SHA-256 and the revision numbers it contains. Append-only.
 */
export const contentSnapshots = pgTable('content_snapshots', {
  id: pk(),
  kind: releaseKind('kind').notNull(),
  sha256: text('sha256').notNull(),
  /** ContentStoreV1 */
  store: json('store').notNull(),
  /** "<type>/<key>" → revision number */
  entityRevisions: jsonb('entity_revisions').notNull(),
  /** Translation states of published records per language (counts and outdated/in-progress items). */
  translations: jsonb('translations').notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  createdBy: uuid('created_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
});

/**
 * Releases (and preview builds). Status changes only through the publishing service, following
 * @soltex/core/domain RELEASE_TRANSITIONS; a trigger keeps the identity, snapshot and artifact
 * columns immutable once set. Every change is also written to release_events.
 */
export const releases = pgTable(
  'releases',
  {
    id: pk(),
    /** R-YYYYMMDD-HHMMSS-xxxxxx (P-… for previews): the artifact directory name. */
    key: text('key').notNull().unique(),
    kind: releaseKind('kind').notNull(),
    status: releaseStatus('status').notNull(),
    snapshotId: uuid('snapshot_id')
      .notNull()
      .references(() => contentSnapshots.id, { onDelete: 'restrict' }),
    /** The release that was active when this one was created / activated over. */
    previousReleaseId: uuid('previous_release_id').references((): AnyPgColumn => releases.id, { onDelete: 'restrict' }),
    /** Optimistic lock for activation / rollback requests. */
    version: integer('version').notNull().default(1),
    attempt: integer('attempt').notNull().default(0),
    note: text('note'),
    /** ReleaseValidationV1: { errors: [], warnings: [], checks: {} } */
    validation: jsonb('validation'),
    /** { step, message } shown in the admin; never a stack trace. */
    failure: jsonb('failure'),
    buildStartedAt: timestamp('build_started_at', { withTimezone: true }),
    buildFinishedAt: timestamp('build_finished_at', { withTimezone: true }),
    heartbeatAt: timestamp('heartbeat_at', { withTimezone: true }),
    artifactSha256: text('artifact_sha256'),
    artifactBytes: bigint('artifact_bytes', { mode: 'number' }),
    artifactFiles: integer('artifact_files'),
    artifactPages: integer('artifact_pages'),
    activatedAt: timestamp('activated_at', { withTimezone: true }),
    activatedBy: uuid('activated_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    createdBy: uuid('created_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
  },
  (t) => [
    index('releases_status').on(t.status),
    index('releases_created').on(t.createdAt),
    // At most one active release (the database guarantees what the symlink shows).
    uniqueIndex('releases_one_active').on(t.kind).where(sql`status = 'active'`),
  ]
);

/** Append-only history of release state changes (who, when, from → to, why). */
export const releaseEvents = pgTable(
  'release_events',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedAlwaysAsIdentity(),
    releaseId: uuid('release_id')
      .notNull()
      .references(() => releases.id, { onDelete: 'restrict' }),
    at: timestamp('at', { withTimezone: true }).notNull().defaultNow(),
    actorId: uuid('actor_id').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    event: text('event').notNull(),
    fromStatus: releaseStatus('from_status'),
    toStatus: releaseStatus('to_status'),
    detail: jsonb('detail').notNull().default(sql`'{}'::jsonb`),
  },
  (t) => [index('release_events_release').on(t.releaseId)]
);

/**
 * Preview access (approved §9): an opaque one-time token (stored as SHA-256) is exchanged on the
 * preview origin for a cookie (also stored as SHA-256). Bound to the user and the admin session
 * that created it; expires after 30 minutes; revoked on «Закрыть предпросмотр» or when the admin
 * session ends.
 */
export const previewGrants = pgTable(
  'preview_grants',
  {
    id: pk(),
    releaseId: uuid('release_id')
      .notNull()
      .references(() => releases.id, { onDelete: 'restrict' }),
    userId: uuid('user_id')
      .notNull()
      .references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    sessionId: uuid('session_id')
      .notNull()
      .references((): AnyPgColumn => sessions.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    cookieHash: text('cookie_hash').unique(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    consumedAt: timestamp('consumed_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
  },
  (t) => [index('preview_grants_user').on(t.userId)]
);

// ===========================================================================
// Leads (Phase K-1, approved §13, review §K; docs/admin-leads.md)
// ===========================================================================

export const leadForm = pgEnum('lead_form', ['cta_section', 'inquiry_modal', 'contact_page']);
export const leadStatus = pgEnum('lead_status', ['new', 'in_progress', 'qualified', 'won', 'lost', 'spam']);
/** approved §13.2: without a consent checkbox in the forms the record is `notice_only`. */
export const consentBasis = pgEnum('consent_basis', ['notice_only', 'checkbox']);
export const leadEventKind = pgEnum('lead_event_kind', ['created', 'status', 'assignee', 'note', 'notified', 'notify_failed', 'deleted', 'restored', 'anonymized']);

/**
 * One inquiry from the site. E-mail, phone and message are encrypted per column (AES-256-GCM,
 * DATA_ENCRYPTION_KEYS with key ids); `*_bidx` are HMAC blind indexes of the normalized e-mail and
 * phone for exact search and duplicate hints. Name and company stay plain for search (approved
 * §13.1). The IP address is stored only as a keyed hash. After anonymization every personal field
 * is null and only date, form, language and status remain.
 */
export const leads = pgTable(
  'leads',
  {
    id: pk(),
    /** SOL-<year>-<number>, shown to the visitor. */
    reference: text('reference').notNull().unique(),
    number: bigint('number', { mode: 'number' }).notNull().unique(),
    formType: leadForm('form_type').notNull(),
    locale: text('locale')
      .notNull()
      .references(() => locales.code),
    pagePath: text('page_path'),
    topic: text('topic'),
    name: text('name'),
    company: text('company'),
    emailEnc: text('email_enc'),
    phoneEnc: text('phone_enc'),
    messageEnc: text('message_enc'),
    emailBidx: text('email_bidx'),
    phoneBidx: text('phone_bidx'),
    ipHash: text('ip_hash'),
    status: leadStatus('status').notNull().default('new'),
    assigneeId: uuid('assignee_id').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    spamScore: integer('spam_score').notNull().default(0),
    spamReasons: text('spam_reasons').array().notNull().default(sql`'{}'::text[]`),
    consentBasis: consentBasis('consent_basis').notNull().default('notice_only'),
    privacyNoticeVersion: text('privacy_notice_version'),
    consentTextVersion: text('consent_text_version'),
    consentAt: timestamp('consent_at', { withTimezone: true }),
    /** First / last touch (Phase K-2, behind ATTRIBUTION_ENABLED). */
    attribution: jsonb('attribution'),
    notifiedAt: timestamp('notified_at', { withTimezone: true }),
    version: integer('version').notNull().default(1),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
    updatedBy: uuid('updated_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    deletedAt: timestamp('deleted_at', { withTimezone: true }),
    deletedBy: uuid('deleted_by').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    anonymizedAt: timestamp('anonymized_at', { withTimezone: true }),
  },
  (t) => [
    index('leads_created').on(t.createdAt),
    index('leads_status').on(t.status),
    index('leads_email_bidx').on(t.emailBidx),
    index('leads_phone_bidx').on(t.phoneBidx),
    check('leads_reference', sql`${t.reference} ~ '^SOL-[0-9]{4}-[0-9]{6,}$'`),
  ]
);

/** History of a lead: who changed what. Notes are encrypted like the lead's own text. */
export const leadEvents = pgTable(
  'lead_events',
  {
    id: pk(),
    leadId: uuid('lead_id')
      .notNull()
      .references(() => leads.id, { onDelete: 'cascade' }),
    at: timestamp('at', { withTimezone: true }).notNull().defaultNow(),
    actorId: uuid('actor_id').references((): AnyPgColumn => users.id, { onDelete: 'restrict' }),
    kind: leadEventKind('kind').notNull(),
    /** Small facts without personal data: { from, to } of a status, an error code, … */
    data: jsonb('data').notNull().default(sql`'{}'::jsonb`),
    noteEnc: text('note_enc'),
  },
  (t) => [index('lead_events_lead').on(t.leadId, t.at)]
);

/**
 * Outbox (approved §19): domain events written in the same transaction as their cause and
 * delivered by the worker with retries, so a lead is never lost when e-mail is down. The payload
 * carries ids only — never personal data; the mail is built from the database when it is sent.
 */
export const outbox = pgTable(
  'outbox',
  {
    id: pk(),
    kind: text('kind').notNull(),
    payload: jsonb('payload').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    attempts: integer('attempts').notNull().default(0),
    nextAttemptAt: timestamp('next_attempt_at', { withTimezone: true }).notNull().defaultNow(),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    /** Error code of the last attempt (never a message with addresses or content). */
    lastError: text('last_error'),
  },
  (t) => [index('outbox_due').on(t.sentAt, t.nextAttemptAt)]
);

/** Numbers of SOL-<year>-<number> references (one sequence; numbers never repeat). */
export const leadNumberSeq = pgSequence('lead_number_seq', { startWith: 1, increment: 1 });
